<template>
  <div>
    <h3>MODEL RESULTS</h3>
    <pre v-if="apiData">{{ formattedApiData }}</pre>
    <p v-else>No data received</p>
  </div>
</template>

<script>
export default {
  name: 'ShowModel',
  computed: {
    apiData() {
      // Debug: Log the raw query parameter
      console.log('Raw query.apiData:', this.$route.query.apiData);
      try {
        const parsedData = this.$route.query.apiData ? JSON.parse(this.$route.query.apiData) : null;
        console.log('Parsed apiData:', parsedData);
        return parsedData;
      } catch (error) {
        console.error('Error parsing apiData:', error);
        return null;
      }
    },
    formattedApiData() {
      return this.apiData ? JSON.stringify(this.apiData, null, 2) : null;
    }
  },
  mounted() {
    // Debug: Log the entire route object on mount
    console.log('ShowModel mounted');
    console.log('Route on mount:', this.$route);
    console.log('Query on mount:', this.$route.query);
  }
};
</script>

<style scoped>
h3 {
  color: #42a5f5; /* Match the blue color from the screenshot */
  text-transform: uppercase;
  margin-bottom: 20px;
}

pre {
  background-color: #f5f5f5;
  padding: 15px;
  border-radius: 5px;
  white-space: pre-wrap;
  word-wrap: break-word;
  color: #000;
}

p {
  color: #fff; /* Match the white color from the screenshot */
}
</style>