<template>
  <div class="model-container">
    <button class="model-btn ml-btn" title="Machine Learning" @click="openModal">ML</button>
    <button class="model-btn img-btn" title="Image Classification">IMG</button>
    <div v-if="showModal" class="modal-overlay">
      <div class="modal-content">
        <h3>Upload CSV File for Machine Learning</h3>
        <input
          type="file"
          ref="fileInput"
          accept=".csv"
          @change="handleFileSelect"
          class="file-input"
        />
        <p v-if="errorMessage" class="error">{{ errorMessage }}</p>
        <p v-if="selectedFile" class="success">Selected: {{ selectedFile.name }}</p>
        <div class="modal-buttons">
          <button @click="submitFile" :disabled="!isValidFile" class="submit-btn">Submit</button>
          <button @click="closeModal" class="cancel-btn">Cancel</button>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import { apiConfig } from '@/config/apiConfig'
export default {
  name: 'ModelName',
  data() {
    return {
      showModal: false,
      selectedFile: null,
      errorMessage: '',
    }
  },
  computed: {
    isValidFile() {
      return this.selectedFile && this.selectedFile.name.endsWith('.csv')
    },
  },
  methods: {
    openModal() {
      this.showModal = true
      this.selectedFile = null
      this.errorMessage = ''
    },
    closeModal() {
      this.showModal = false
      this.selectedFile = null
      this.errorMessage = ''
      this.$refs.fileInput.value = ''
    },
    handleFileSelect(event) {
  const file = event.target.files[0]
  if (file) {
    if (file.name.endsWith('.csv')) {
      this.selectedFile = file
      this.errorMessage = ''
      // Print file details
      console.log('Selected File:', {
        name: file.name,
        type: file.type,
        size: file.size,
        lastModified: new Date(file.lastModified).toISOString()
      })
    } else {
      this.selectedFile = null
      this.errorMessage = 'Please select a CSV file.'
      this.$refs.fileInput.value = ''
    }
  } else {
    this.selectedFile = null
    this.errorMessage = ''
  }
},
    
    async submitFile() {
      if (this.isValidFile) {
        const formData = new FormData()
        
        // formData.append('data_path', this.selectedFile.name)
        
        formData.append('file', this.selectedFile) 

        for (const [key, value] of formData.entries()) {
      console.log(`FormData Entry - ${key}:`, value)
      }

        try {
          const response = await fetch(apiConfig.endpoints.loadDataEndpoint(), {
            method: 'POST',
            body: formData
          })

          // Handle different status codes
          if (response.ok) { // 200-299
            const data = await response.json()
            this.$router.push({
          name: 'SelectModel', // Route name for SelectModel.vue
          state: { apiData: data } // Pass the API response data via state
        });
          } else if (response.status === 400) {
            const errorData = await response.json()
            this.errorMessage = errorData.message || 'Bad request: Invalid file or data.'
          } else if (response.status === 401) {
            this.errorMessage = 'Unauthorized: Please check your credentials.'
          } else if (response.status === 403) {
            this.errorMessage = 'Forbidden: You do not have permission to perform this action.'
          } else if (response.status === 404) {
            this.errorMessage = 'Not found: The API endpoint does not exist.'
          } else if (response.status >= 500) {
            this.errorMessage = 'Server error: Please try again later.'
          } else {
            this.errorMessage = `Unexpected error: ${response.status} - ${response.statusText}`
          }
        } catch (error) {
          console.error('Error submitting file:', error)
          this.errorMessage = 'Network error: Failed to connect to the server.'
        }

        
        if (!this.errorMessage) {
          this.closeModal()
        }
      }
    }
  }
}
</script>

<style scoped>
.model-container::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: url('/src/assets/logo.png'), no-repeat, center 60% / contain;
  opacity: 0.1;
  z-index: -1;
}

.ml-btn::after {
  content: '📊';
  margin-left: 5px;
}

.img-btn::after {
  content: '🖼️';
  margin-left: 5px;
}
</style>