  text-overflow: ellipsis;
  flex: 1;
}

.arrow {
  font-size: 0.8rem;
}

.checklist {
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  background: var(--card-bg);
  border: 1px solid var(--secondary-color);
  border-radius: 5px;
  box-shadow: var(--shadow);
  max-height: 200px;
  color: aqua;
  overflow-y: auto;
  z-index: 10;
  padding: 5px 0;
}

.checklist label {
  display: flex;
  align-items: center;
  padding: 8px 12px;
  cursor: pointer;
  font-size: 0.95rem;
  transition: background 0.2s ease;
}

.checklist label:hover {
  background: rgba(0, 0, 0, 0.2);
}

.checklist label.disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.checklist input {
  margin-right: 8px;
}

.search-input {
  width: 100%;
  padding: 8px;
  margin-bottom: 5px;
  border: 1px solid var(--secondary-color);
  border-radius: 5px;
  font-size: 0.95rem;
  box-sizing: border-box;
}

.no-results {
  padding: 8px 12px;
  color: var(--error-color);
  font-size: 0.9rem;
}

.selected-text {
  font-size: 0.85rem;
  margin-top: 5px;
}

/* Enhanced Radio Group Styling */
.radio-group-enhanced {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: rgba(0, 0, 0, 0.05);
  padding: 10px;
  border-radius: 5px;
  border: 1px solid var(--secondary-color);
}

.radio-label {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px 15px;
  border-radius: 20px;
  transition: background 0.3s ease;
}

.radio-label:hover {
  background: rgba(0, 0, 0, 0.1);
}

.radio-label input[type="radio"] {
  appearance: none;
  width: 18px;
  height: 18px;
  border: 2px solid var(--secondary-color);
  border-radius: 50%;
  position: relative;
  cursor: pointer;
}

.radio-label input[type="radio"]:checked {
  border-color: var(--secondary-color);
  background: var(--secondary-color);
}

.radio-label input[type="radio"]:checked::after {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--bg-color);
}

.radio-label input[type="radio"]:focus {
  outline: none;
  box-shadow: 0 0 5px var(--secondary-color);
}

.radio-text {
  font-size: 1rem;
  color: var(--text-color);
}

/* Path Input */
.path-input-wrapper {
  display: flex;
  gap: 10px;
}

.path-input-wrapper input {
  flex: 1;
  padding: 10px;
  border: 1px solid var(--secondary-color);
  border-radius: 5px;
  background: var(--card-bg);
}

.folder-btn {
  padding: 10px;
  background: var(--button-bg);
  color: var(--bg-color);
  border: none;
  border-radius: 5px;
  cursor: pointer;
  transition: background 0.3s ease;
}

.folder-btn:hover {
  background: var(--button-hover);
}

/* Submit Button */
.submit-section {
  text-align: center;
  margin-top: 30px;
}
</style>