<template>
  <div id="app">
    <label class="dark-mode-toggle">
      <input
        type="checkbox"
        id="dark-mode-switch"
        v-model="isDarkMode"
        @change="toggleDarkMode"
      >
      <span class="slider"></span>
    </label>
    <RouterView />
  </div>
</template>

<script>
export default {
  name: 'App',
  data() {
    return {
      isDarkMode: false
    }
  },
  methods: {
    toggleDarkMode() {
      console.log('Toggling dark mode to:', this.isDarkMode ? 'dark' : 'light') // Debug log
      document.documentElement.setAttribute('data-theme', this.isDarkMode ? 'dark' : 'light')
    }
  },
  mounted() {
    // Initialize theme based on localStorage or default
    const savedTheme = localStorage.getItem('theme')
    this.isDarkMode = savedTheme === 'dark'
    console.log('Initial theme:', this.isDarkMode ? 'dark' : 'light') // Debug log
    document.documentElement.setAttribute('data-theme', this.isDarkMode ? 'dark' : 'light')
  },
  watch: {
    isDarkMode(newValue) {
      console.log('Theme changed to:', newValue ? 'dark' : 'light') // Debug log
      localStorage.setItem('theme', newValue ? 'dark' : 'light')
    }
  }
}
</script>

