// router/index.js
import { createRouter, createWebHistory } from 'vue-router'
import Welcome from '../components/welcome.vue'
import ModelName from '../components/ModelName.vue'
import SelectModal  from '../components/SelectModal.vue'
import ShowModel from '../components/ShowModel.vue'
import BigPrac from '@/components/BigPrac.vue'
const routes = [
  {
    path: '/',
    name: 'Welcome',
    component: Welcome
  },
  {
    path: '/modelname',
    name: 'ModelName',
    component: ModelName
  },
  {
    path: '/defaultmodel',
    name: 'MainModel',
    component: ModelName
  },
  {
    path: '/select-model',
    name: 'SelectModel',
    component: SelectModal
  },
  {
  path: '/show-model',
  name: 'ShowModel',
  component: ShowModel
},
  {
  path: '/big',
  name: 'BigPrac',
  component: BigPrac
}
  
]

const router = createRouter({
  history: createWebHistory(),
  routes
})

export default router